import{_ as r,l as d,o as e,c as n,v as t,p as l,x as i,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"MSD 同步误差","description":"","frontmatter":{"title":"MSD 同步误差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/msd-moving-standard-deviation.md","filePath":"litho/msd-moving-standard-deviation.md","lastUpdated":1789023840000}'),m={name:"litho/msd-moving-standard-deviation.md"};function c(_,a,E,A,S,D){const o=d("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="msd-同步误差" tabindex="-1">MSD 同步误差 <a class="header-anchor" href="#msd-同步误差" aria-label="Permalink to &quot;MSD 同步误差&quot;">​</a></h1><div class="epigraph"><p>扫描要求掩模台与工件台按倍率同步。MSD 是相对位置误差的运动标准差：它糊边，像一架振动的狭缝。</p><footer>—— 对照 moving standard deviation 同步误差；[狭缝扫描平均](/litho/slit-scan-average)</footer></div><p><a href="/litho/stage-acceleration-throughput">上一课</a>把加速写进产能。缺口是匀速扫描段两台是否锁住。本课钉 MSD，不重写套刻向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投影倍率把掩模运动与晶圆运动绑在一起。相对误差随时间变，积分到像上是沿扫描向的模糊，NILS 掉、LER 升。编码器各报各的「很准」，相对不准一样废。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>伺服用相对误差作被控量。指标 MSD（moving standard deviation）在扫描窗上算。降 MSD：更硬的控制、更低加速度残振、更好的位置计量。与剂量扫描平均不同：剂量平均强度，MSD 平均的是位置噪声。</p>',7)),(e(),l(p,null,{default:i(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RT%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%B0%22%5D%20--%3E%20REL%5B%22%E7%9B%B8%E5%AF%B9%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20WF%5B%22%E5%B7%A5%E4%BB%B6%E5%8F%B0%22%5D%20--%3E%20REL%0A%20%20REL%20--%3E%20MSD%5B%22%E6%89%AB%E6%8F%8F%E7%AA%97%20MSD%22%5D%0A%20%20MSD%20--%3E%20BLUR%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%E6%A8%A1%E7%B3%8A%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">High-NA 半场拼接对同步更苛刻：两场接缝处 MSD 会变成可见错位。见 High-NA 课，本课只钉指标。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>像面位移 \\(\\approx\\) 相对台误差 / 倍率关系。时间上的抖动被狭缝驻留时间卷积，等效低通模糊。高频抖更伤边缘。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课温控：热使尺和空气变，MSD 和干涉仪一起漂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MSD 是两台相对误差的扫描统计，直接糊边。</li><li>单台精度好不等于同步好。</li><li>出处：狭缝课；扫描同步通识。</li></ul>',7))])}const f=r(m,[["render",c]]);export{B as __pageData,f as default};
